CREATE TABLE Rasy 
(
    Nazwa VARCHAR(255) PRIMARY KEY,
    Rozumność BOOLEAN NOT NULL,
    Siła_OCENA INTEGER NOT NULL CONSTRAINT Siła_ZAKRES CHECK(Siła_OCENA BETWEEN 1 AND 30*2),
    Wytrzymałość_OCENA INTEGER NOT NULL CONSTRAINT Wytrzymałość_ZAKRES CHECK(Wytrzymałość_OCENA BETWEEN 1 AND 30*2),
    Kondycja_OCENA INTEGER NOT NULL CONSTRAINT Kondycja_ZAKRES CHECK(Kondycja_OCENA BETWEEN 1 AND 30*2),
    Zręczność_OCENA INTEGER NOT NULL CONSTRAINT Zręczność_ZAKRES CHECK(Zręczność_OCENA BETWEEN 1 AND 30*2),
    Zwinność_OCENA INTEGER NOT NULL CONSTRAINT Zwinność_ZAKRES CHECK(Zwinność_OCENA BETWEEN 1 AND 30*2),
    MAGICZNOŚĆ INTEGER NOT NULL CONSTRAINT MAGICZNOŚĆ_ZAKRES CHECK(MAGICZNOŚĆ BETWEEN 1 AND 10*2),
    Mądrość_OCENA INTEGER NOT NULL CONSTRAINT Mądrość_ZAKRES CHECK(Mądrość_OCENA BETWEEN 1 AND 10*2),
    Inteligencja_OCENA INTEGER NOT NULL CONSTRAINT Inteligencja_ZAKRES CHECK(Inteligencja_OCENA BETWEEN 1 AND 10*2),
    Charyzma_OCENA INTEGER NOT NULL CONSTRAINT Charyzma_ZAKRES CHECK(Charyzma_OCENA BETWEEN 1 AND 20*2),
    Pobożność_OCENA INTEGER NOT NULL CONSTRAINT Pobożność_ZAKRES CHECK(Pobożność_OCENA BETWEEN 1 AND 20*2),
    Wola_OCENA INTEGER NOT NULL CONSTRAINT Wola_ZAKRES CHECK(Wola_OCENA BETWEEN 1 AND 20*2),
    Zdolności_rasowe TEXT,
    Pancerz_Ogólny INTEGER NOT NULL CONSTRAINT naturalne_Pancerz_Ogólny_Rasy CHECK(Pancerz_Ogólny>=0),
    Pancerz_miękki INTEGER NOT NULL CONSTRAINT naturalne_Pancerz_miękki_Rasy CHECK(Pancerz_miękki>=0),
    Pancerz_twardy INTEGER NOT NULL CONSTRAINT naturalne_Pancerz_twardy_Rasy CHECK(Pancerz_twardy>=0),
    Ochrona_przed_zimnem INTEGER CONSTRAINT naturalne_Ochrona_przed_zimnem_Rasy CHECK(Ochrona_przed_zimnem>=0),
    Typ_przejęcia VARCHAR(255) CONSTRAINT Typy_przejęcia CHECK(Typ_przejęcia in
        (
        'Zwierzęce(animal soul)',
        'Bestii(Beast soul)',
        'Maszyny(Machina soul)',
        'Szatana(Satan soul)',
        'bożka(goddo soul)'
        )
    ),
    Występowanie_rola_informacje TEXT,
    średnia_długość_życia INTEGER CONSTRAINT naturalne_średnia_długość_życia_Rasy CHECK(średnia_długość_życia >= 0),
    wiek_starości INTEGER NOT NULL CONSTRAINT naturalne_wiek_starości_Rasy CHECK(wiek_starości >= 0),
    inne_cechy TEXT
);

CREATE TABLE Postacie
(
    --identyfikacja
    ID_postaci SERIAL PRIMARY KEY,
    Imię VARCHAR(255) NOT NULL,
    Nazwisko VARCHAR(255),
    --rozwój
    Poziom INTEGER NOT NULL CONSTRAINT dodatnie_Poziom_Postacie CHECK(Poziom>0),
    PD BIGINT NOT NULL CONSTRAINT naturalne_PD_Postacie CHECK(PD>=0) DEFAULT 0,
    Wiek INTEGER CONSTRAINT dodatnie_Wiek_Postacie CHECK(Wiek>0),
    --przydział cech 1 poziom
    Siła_poziom_1 INTEGER NOT NULL 
        CONSTRAINT ograniczenie_ujemności_Siła_poziom_1 CHECK(Siła_poziom_1>=-3),
    Wytrzymałość_poziom_1 INTEGER NOT NULL
        CONSTRAINT ograniczenie_ujemności_Wytrzymałość_poziom_1 CHECK(Wytrzymałość_poziom_1>=-3),
    Kondycja_poziom_1 INTEGER NOT NULL
        CONSTRAINT ograniczenie_ujemności_Kondycja_poziom_1 CHECK(Kondycja_poziom_1>=-3),
    Zręczność_poziom_1 INTEGER NOT NULL 
        CONSTRAINT ograniczenie_ujemności_Zręczność_poziom_1 CHECK(Zręczność_poziom_1>=-3),
    Zwinność_poziom_1 INTEGER NOT NULL 
        CONSTRAINT ograniczenie_ujemności_Zwinność_poziom_1 CHECK(Zwinność_poziom_1>=-3),
    Mądrość_poziom_1 INTEGER NOT NULL 
        CONSTRAINT ograniczenie_ujemności_Mądrość_poziom_1 CHECK(Mądrość_poziom_1>=-3),
    Inteligencja_poziom_1 INTEGER NOT NULL 
        CONSTRAINT ograniczenie_ujemności_Inteligencja_poziom_1 CHECK(Inteligencja_poziom_1>=-3),
    Charyzma_poziom_1 INTEGER NOT NULL
        CONSTRAINT ograniczenie_ujemności_Charyzma_poziom_1 CHECK(Charyzma_poziom_1>=-3),
    Pobożność_poziom_1 INTEGER NOT NULL 
        CONSTRAINT ograniczenie_ujemności_Pobożność_poziom_1 CHECK(Pobożność_poziom_1>=-3),
    Wola_poziom_1 INTEGER NOT NULL
        CONSTRAINT ograniczenie_ujemności_Wola_poziom_1 CHECK(Wola_poziom_1>=-3),
    --przydział cech wyższe poziomy
    Siła_z_awansów INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Siła_z_awansów CHECK(Siła_z_awansów>=0),
    Wytrzymałość_z_awansów INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Wytrzymałość_z_awansów CHECK(Wytrzymałość_z_awansów>=0),
    Kondycja_z_awansów INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Kondycja_z_awansów CHECK(Kondycja_z_awansów>=0),
    Zręczność_z_awansów INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Zręczność_z_awansów CHECK(Zręczność_z_awansów>=0),
    Zwinność_z_awansów INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Zwinność_z_awansów CHECK(Zwinność_z_awansów>=0),
    Mądrość_z_awansów INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Mądrość_z_awansów CHECK(Mądrość_z_awansów>=0),
    Inteligencja_z_awansów INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Inteligencja_z_awansów CHECK(Inteligencja_z_awansów>=0),
    Charyzma_z_awansów INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Charyzma_z_awansów CHECK(Charyzma_z_awansów>=0),
    Pobożność_z_awansów INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Pobożność_z_awansów CHECK(Pobożność_z_awansów>=0),
    Wola_z_awansów INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Wola_z_awansów CHECK(Wola_z_awansów>=0),
    --przydział cech klasowych(przydzielane podczas awansu)
    Siła_klasowa INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Siła_klasowa CHECK(Siła_klasowa>=0),
    Wytrzymałość_klasowa INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Wytrzymałość_klasowa CHECK(Wytrzymałość_klasowa>=0),
    Kondycja_klasowa INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Kondycja_klasowa CHECK(Kondycja_klasowa>=0),
    Zręczność_klasowa INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Zręczność_klasowa CHECK(Zręczność_klasowa>=0),
    Zwinność_klasowa INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Zwinność_klasowa CHECK(Zwinność_klasowa>=0),
    Mądrość_klasowa INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Mądrość_klasowa CHECK(Mądrość_klasowa>=0),
    Inteligencja_klasowa INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Inteligencja_klasowa CHECK(Inteligencja_klasowa>=0),
    Charyzma_klasowa INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Charyzma_klasowa CHECK(Charyzma_klasowa>=0),
    Pobożność_klasowa INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Pobożność_klasowa CHECK(Pobożność_klasowa>=0),
    Wola_klasowa INTEGER NOT NULL DEFAULT 0
        CONSTRAINT naturalne_Wola_klasowa CHECK(Wola_klasowa>=0),
    --
    Rasy_Nazwa VARCHAR(255) NOT NULL,
    Gracz VARCHAR(255),
    --ograniczenia złożone
    CONSTRAINT Postacie_poziom1 
        Check
        (
            Siła_poziom_1 
            + Wytrzymałość_poziom_1
            + Kondycja_poziom_1
            + Zręczność_poziom_1
            + Zwinność_poziom_1
            + Mądrość_poziom_1
            + Inteligencja_poziom_1
            + Charyzma_poziom_1
            + Pobożność_poziom_1
            + Wola_poziom_1
            <=50
        ),
    CONSTRAINT Postacie_awanse
        Check
        (
            Siła_z_awansów 
            + Wytrzymałość_z_awansów
            + Kondycja_z_awansów
            + Zręczność_z_awansów
            + Zwinność_z_awansów
            + Mądrość_z_awansów
            + Inteligencja_z_awansów
            + Charyzma_z_awansów
            + Pobożność_z_awansów
            + Wola_z_awansów
            <=10*(Poziom-1)
        )
        --pożądanym stanem jest technicznie rzecz biorąc to by te sumy były "=" odpowiednio 50 i 10*(poziom-1)
        --ale przydzielenie mniej jest dopuszczalne
    --CONSTRAINT Postacie_PK PRIMARY KEY (Imię, Nazwisko)
);

CREATE TABLE Umiejętności 
(
    Nazwa VARCHAR(255) PRIMARY KEY,
    Poboczna BOOLEAN NOT NULL,
    Natura VARCHAR(255) NOT NULL CHECK(Natura in ('Fizyczna','Błogosławieństwa','Magia','Klątwy')),--Fizyczna // Błogosławieństwa / Magia / Klątwy
    Rodzaj VARCHAR(255) CHECK(Rodzaj in ('typ', 'atrybut', 'umiejętność szczegółowa', 'specjalizacja')),--typ / atrybut / umiejętność szczegółowa / specjalizacja
    Samodzielność VARCHAR(255) NOT NULL CHECK(Samodzielność in ('kategoria(+1)', 'kategoria', 'umiejętność')),--kategoria(+1) / kategoria / umiejętność
    Dostępność VARCHAR(255) NOT NULL CHECK(Dostępność in ('zaginiona', 'rzadka', 'powszechna')),--zaginiona / rzadka / powszechna
    Opis_fabularny TEXT,
    Opis_praktyczny TEXT
);

CREATE TABLE Klasy
(
    nazwa VARCHAR(255) PRIMARY KEY,
    premiowana_cecha1 VARCHAR(255) 
        CONSTRAINT Lista_Cech_premCecha1
            CHECK(premiowana_cecha1 IN 
            (
                'Siła','Wytrzymałość','Kondycja','Zręczność','Zwinność','Mądrość','Inteligencja','Charyzma','Pobożność','Wola'
            )),
    premiowana_cecha2 VARCHAR(255)
        CONSTRAINT Lista_Cech_premCecha2
            CHECK(premiowana_cecha2 IN 
            (
                'Siła','Wytrzymałość','Kondycja','Zręczność','Zwinność','Mądrość','Inteligencja','Charyzma','Pobożność','Wola'
            )),
    premiowana_cecha3 VARCHAR(255)
        CONSTRAINT Lista_Cech_premCecha3
            CHECK(premiowana_cecha2 IN 
            (
                'Siła','Wytrzymałość','Kondycja','Zręczność','Zwinność','Mądrość','Inteligencja','Charyzma','Pobożność','Wola'
            ))
);

