CREATE TABLE Klasy_Przeciwników (
    nazwa VARCHAR(255) PRIMARY KEY,
    opis TEXT,
    minimalny_poziom INTEGER CONSTRAINT dodatnie_minimalny_poziom_Klasy_Przeciwników CHECK(minimalny_poziom>0),
    maksymalny_poziom INTEGER CONSTRAINT dodatnie_maksymalny_poziom_Klasy_Przeciwników CHECK(maksymalny_poziom>0),
    Siła_poziom_1 INTEGER NOT NULL DEFAULT 0,
    Wytrzymałość_poziom_1 INTEGER NOT NULL DEFAULT 0,
    Kondycja_poziom_1 INTEGER NOT NULL DEFAULT 0,
    Zręczność_poziom_1 INTEGER NOT NULL DEFAULT 0,
    Zwinność_poziom_1 INTEGER NOT NULL DEFAULT 0,
    Mądrość_poziom_1 INTEGER NOT NULL DEFAULT 0,
    Inteligencja_poziom_1 INTEGER NOT NULL DEFAULT 0,
    Charyzma_poziom_1 INTEGER NOT NULL DEFAULT 0,
    Pobożność_poziom_1 INTEGER NOT NULL DEFAULT 0,
    Wola_poziom_1 INTEGER NOT NULL DEFAULT 0,
    Siła_na_awans INTEGER NOT NULL
        CONSTRAINT naturalne_Siła_na_awans_Klasy_Przeciwników CHECK(Siła_na_awans>=0),
    Wytrzymałość_na_awans INTEGER NOT NULL
        CONSTRAINT naturalne_Wytrzymałość_na_awans_Klasy_Przeciwników CHECK(Wytrzymałość_na_awans>=0),
    Kondycja_na_awans INTEGER NOT NULL
        CONSTRAINT naturalne_Kondycja_na_awans_Klasy_Przeciwników CHECK(Kondycja_na_awans>=0),
    Zręczność_na_awans INTEGER NOT NULL
        CONSTRAINT naturalne_Zręczność_na_awans_Klasy_Przeciwników CHECK(Zręczność_na_awans>=0),
    Zwinność_na_awans INTEGER NOT NULL
        CONSTRAINT naturalne_Zwinność_na_awans_Klasy_Przeciwników CHECK(Zwinność_na_awans>=0),
    Mądrość_na_awans INTEGER NOT NULL
        CONSTRAINT naturalne_Mądrość_na_awans_Klasy_Przeciwników CHECK(Mądrość_na_awans>=0),
    Inteligencja_na_awans INTEGER NOT NULL
        CONSTRAINT naturalne_Inteligencja_na_awans_Klasy_Przeciwników CHECK(Inteligencja_na_awans>=0),
    Charyzma_na_awans INTEGER NOT NULL 
        CONSTRAINT naturalne_Charyzma_na_awans_Klasy_Przeciwników CHECK(Charyzma_na_awans>=0),
    Pobożność_na_awans INTEGER NOT NULL 
        CONSTRAINT naturalne_Pobożność_na_awans_Klasy_Przeciwników CHECK(Pobożność_na_awans>=0),
    Wola_na_awans INTEGER NOT NULL CONSTRAINT naturalne_Wola_na_awans_Klasy_Przeciwników CHECK(Wola_na_awans>=0),
    Rasy_Nazwa VARCHAR(255) NOT NULL,
    CONSTRAINT Klasy_Przeciwników_zakres_poziomów
        CHECK (minimalny_poziom <= maksymalny_poziom)
);

CREATE TABLE Waluty
(
    nazwa VARCHAR(255) PRIMARY KEY,
    Przelicznik_na_główną_walutę NUMERIC(16,8) NOT NULL DEFAULT 1 CHECK (Przelicznik_na_główną_walutę >= 0),--przyjmuje, że waluty i nominały nie będą mniej niż 100^4 razy większe lub mniejsze od głównej waluty, 0 to wartość dla walut okazujnych jak talony itp. których nie można po prostu wymienić z powrotem na pieniądze
    Główna BOOLEAN NOT NULL DEFAULT FALSE
);


