--2.B Techniki - Główna, zależna od umiejętności i przedmiotów
CREATE TABLE Techniki
(
    nazwa VARCHAR(255) PRIMARY KEY,
    typ VARCHAR(255) NOT NULL CONSTRAINT Techniki_typ_CHECK CHECK(typ IN ('bazowa', 'ogólna', 'konkretna')),
    --kategoria_funkcjonalna VARCHAR(255),--wydzielono jako tabele
    bazowy_koszt_w_manie INTEGER NOT NULL CONSTRAINT naturalne_bazowy_koszt_w_manie CHECK(bazowy_koszt_w_manie>=0),
    modyfikatory_kosztu_w_manie VARCHAR(255),
    bazowy_koszt_w_energii INTEGER NOT NULL CONSTRAINT naturalne_bazowy_koszt_w_energii CHECK(bazowy_koszt_w_energii>=0),
    modyfikatory_kosztu_w_energii VARCHAR(255),
    efekt TEXT NOT NULL,
    test_sukcesu VARCHAR(255) NOT NULL,
    test_trafienia VARCHAR(255),
    testy_obrażeń VARCHAR(255),
    test_na_zniszczenie VARCHAR(255),
    ew_inne_testy VARCHAR(255),
    Umiejętności_Nazwa VARCHAR(255),
    --Bronie_Umiejętności_Nazwa VARCHAR(255),--dublowanie z powyższą 
    minimalny_poziom_nauki INTEGER CONSTRAINT naturalne_minimalny_poziom_nauki CHECK(minimalny_poziom_nauki>=0),
    stopień_zaawansowania VARCHAR(255),
    wymagania_specjalne VARCHAR(255),--do użycia - dodatkowe względem samych przedmiotów
    ---dodatkowy wymóg do samej nauki(nie do wykonania): nigdy, rzadko, czasem, zazwyczaj, często, zawsze 
    Wymaga_nauki_z_księgii VARCHAR(255),
    Wymaga_nauczyciela VARCHAR(255),
    Wymaga_dodatkowego_treningu VARCHAR(255)
);

--2.C Tabele Umiejętnościowe i Technikowe:
--2.C.1 Wewnętrzne:
CREATE TABLE Podległość
(
    wymagana_nadrzędna VARCHAR(255) NOT NULL,
    podrzędna VARCHAR(255) NOT NULL,--umiejętność wymagająca równego wyższego poziomu nadrzędnej-wymaganej
    minimalny_poziom INTEGER DEFAULT 0 NOT NULL Constraint naturalne_minimalny_poziom_Podległość CHECK(minimalny_poziom>=0),
    CONSTRAINT Podległość_PK PRIMARY KEY (wymagana_nadrzędna, podrzędna)
);

CREATE TABLE Kategorie_technik
(
    nazwa VARCHAR(255) PRIMARY KEY,
    opis TEXT
);

CREATE TABLE Techniki_Kategorie
(
    Techniki_nazwa VARCHAR(255) NOT NULL
        REFERENCES Techniki(nazwa),
    Kategorie_technik_nazwa VARCHAR(255) NOT NULL
        REFERENCES Kategorie_technik(nazwa),
    PRIMARY KEY (Techniki_nazwa, Kategorie_technik_nazwa)
);

--2.C.2 Postaciowe
CREATE TABLE Opanowane 
(
    Umiejętności_Nazwa VARCHAR(255) NOT NULL,
    Postacie_ID INTEGER NOT NULL,
    poziom INTEGER CONSTRAINT dodatnie_poziom_Opanowane CHECK(poziom>0),
    CONSTRAINT Opanowane_PK PRIMARY KEY (Postacie_ID, Umiejętności_Nazwa)
);

CREATE TABLE zna
(
    Techniki_nazwa VARCHAR(255) NOT NULL,
    Postacie_ID INTEGER NOT NULL,
    poziom_poznania INTEGER NOT NULL CONSTRAINT naturalne_zna CHECK(poziom_poznania>=0),-- poziom umiejętności, na którym poznało się daną technikę
    CONSTRAINT zna_PK PRIMARY KEY (Techniki_nazwa, Postacie_ID)
);

--2.C.3 Przeciwnikowe
CREATE TABLE umiejętności_przeciwników (
    Klasy_Przeciwników_nazwa VARCHAR(255) NOT NULL,
    Umiejętności_Nazwa VARCHAR(255) NOT NULL,
    CONSTRAINT umiejętności_przeciwników_PK PRIMARY KEY (Klasy_Przeciwników_nazwa, Umiejętności_Nazwa)
);

CREATE TABLE przeciwnicy_znają
(
    Klasy_Przeciwników_nazwa VARCHAR(255) NOT NULL,
    Techniki_nazwa VARCHAR(255) NOT NULL,
    CONSTRAINT przeciwnicy_znają_PK PRIMARY KEY (Klasy_Przeciwników_nazwa, Techniki_nazwa)
);


--2.C.4 Księgowe
CREATE TABLE umiejętności_uczone_z_ksiąg (
    Umiejętności_Nazwa VARCHAR(255) NOT NULL,
    Księgi_i_Pisma_Przedmioty_Przed_Nazwa VARCHAR(255) NOT NULL,
    CONSTRAINT umiejętności_uczone_z_ksiąg_PK PRIMARY KEY (Umiejętności_Nazwa, Księgi_i_Pisma_Przedmioty_Przed_Nazwa)
);

CREATE TABLE Techniki_uczone_z_ksiąg (
    Księgi_i_Pisma_Przedmioty_Przed_Nazwa VARCHAR(255) NOT NULL,
    Techniki_nazwa VARCHAR(255) NOT NULL,
    CONSTRAINT Techniki_uczone_z_ksiąg_PK PRIMARY KEY (Techniki_nazwa, Księgi_i_Pisma_Przedmioty_Przed_Nazwa)
);

CREATE TABLE Techniki_przedmiotów--techniki wymagające przedmiotu do wykonania
(--Techniki_przedmiotów
    Przed_Nazwa VARCHAR(255) NOT NULL
        REFERENCES Przedmioty(Przed_Nazwa),
    Techniki_nazwa VARCHAR(255) NOT NULL
        REFERENCES Techniki(nazwa),
    liczba_potrzebnych INTEGER NOT NULL DEFAULT 1 CHECK (liczba_potrzebnych > 0),
    ----Wystarczy BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT Techniki_przedmiotów_PK PRIMARY KEY (Przed_Nazwa, Techniki_nazwa)
);

-----===============
--2.D Tabele Klasowe

CREATE TABLE Rangi_klasowe
(
    --Stopień INTEGER NOT NULL CONSTRAINT naturalne CHECK(Stopień>=0),--która z kolei to ranga w danej klasie
    Nazwa VARCHAR(255) NOT NULL,
    bonusy_za_rangę TEXT,
    --bonus_do_cech_na_poziom NUMERIC(8, 7),
    bonus_do_cech_co_poziomów INTEGER NOT NULL
        CONSTRAINT naturalne_bonus_do_cech_co_poziomów_Rangi_klasowe CHECK(bonus_do_cech_co_poziomów>0),
    bonus_do_cech_wartość NUMERIC(2, 1) NOT NULL
        CONSTRAINT naturalne_bonus_do_cech_wartość_Rangi_klasowe CHECK(bonus_do_cech_wartość>0),
    punkty_cech_na_awans INTEGER NOT NULL 
        CONSTRAINT naturalne_punkty_cech_na_awans_Rangi_klasowe CHECK(punkty_cech_na_awans>=0),
    minimalne_punkty_klasowe INTEGER NOT NULL
        CONSTRAINT dodatnie_minimalne_punkty_klasowe_Rangi_klasowe CHECK(minimalne_punkty_klasowe>0),
    --punkty_klasowe_wymagane_do_awansu INTEGER CONSTRAINT dodatnie CHECK(punkty_klasowe_wymagane_do_awansu>0),
        --nadmiarowe, osiągalne(a więc dublujące się z) przez join po następna ranga i wybraniu minimalne_punkty_klasowe  
    Klasa_nazwa VARCHAR(255) NOT NULL,
    Poprzednia_ranga VARCHAR(255),
    Nastepna_ranga VARCHAR(255),
    CONSTRAINT Rangi_klasowe_PK PRIMARY KEY (Nazwa, Klasa_nazwa)
    --CONSTRAINT Rangi_klasowe_punkty (minimalne_punkty_klasowe<punkty_klasowe_wymagane_do_awansu)
);

CREATE TABLE klasa_postaci
(
    ilość_punktów_klasowych INTEGER
        CONSTRAINT naturalne_ilość_punktów_klasowych_klasa_postaci CHECK(ilość_punktów_klasowych>=0) NOT NULL,
    ilość_punktów_klasowych_z_cech INTEGER
        CONSTRAINT naturalne_ilość_punktów_klasowych_z_cech_klasa_postaci CHECK(ilość_punktów_klasowych_z_cech>=0) NOT NULL,
    Postacie_ID INTEGER NOT NULL,
    Klasa_nazwa VARCHAR(255) NOT NULL,
    Rangi_klasowe_Nazwa VARCHAR(255) NOT NULL,
    --Rangi_klasowe_Klasa_nazwa VARCHAR(255),-- NOT NULL,
    aktywna BOOLEAN,
    CONSTRAINT klasa_postaci_PK PRIMARY KEY (Postacie_ID, Klasa_nazwa)
);

CREATE TABLE Punkty_Klasowe (
    Warunek VARCHAR(255) NOT NULL,
    minimalne_punkty INTEGER,
    maksymalne_punkty INTEGER,
    Klasa_nazwa VARCHAR(255) NOT NULL,
    CONSTRAINT Punkty_Klasowe_PK PRIMARY KEY (Klasa_nazwa, Warunek),
    CONSTRAINT Punkty_Klasowe_punkty CHECK(ABS(minimalne_punkty) <= ABS(maksymalne_punkty))
);


