-- ==========================================
-- 4. Trigery - funkcje więzów integralności
-- ==========================================

-- kontrola, większy poziom(poziom postaci, poziom umiejętności nadrzędnej): 
--- CEL: poziom postaci >= poziom umiejętności
CREATE OR REPLACE FUNCTION sprawdz_poziom_umiejetnosci()
RETURNS trigger AS
$$
DECLARE
    poziom_postaci INTEGER;
    maksymalny_poziom_umiejetnosci INTEGER;
BEGIN

    SELECT Poziom
    INTO poziom_postaci
    FROM Postacie
    WHERE ID_postaci = NEW.Postacie_ID;

    maksymalny_poziom_umiejetnosci :=
        CASE
            WHEN poziom_postaci = 1 THEN 2
            ELSE poziom_postaci
        END;

    IF NEW.poziom > maksymalny_poziom_umiejetnosci THEN
        RAISE EXCEPTION
            'Poziom umiejętności (%) przekracza dopuszczalny poziom (%).',
            NEW.poziom,
            maksymalny_poziom_umiejetnosci;
    END IF;

    RETURN NEW;
END;
$$
LANGUAGE plpgsql;
--- CEL: poziom postaci >= poziom umiejętności
CREATE TRIGGER trg_sprawdz_poziom
BEFORE INSERT OR UPDATE
ON Opanowane
FOR EACH ROW
EXECUTE FUNCTION sprawdz_poziom_umiejetnosci();

--- poziom umiejętności wymaganej(wymagana_nadrzędna) >= poziom umiejętności wymagającej(wymaga)
CREATE OR REPLACE FUNCTION sprawdz_zaleznosci_postaci(
    p_postac_id INTEGER
)
RETURNS VOID
AS
$$
DECLARE
    naruszenie RECORD;
BEGIN

    SELECT
        p.wymagana_nadrzędna,
        p.podrzędna,
        p.minimalny_poziom,
        podrz.poziom AS poziom_podrzednej,
        nadrz.poziom AS poziom_nadrzednej
    INTO naruszenie
    FROM Podległość p

    JOIN Opanowane podrz
      ON podrz.Umiejętności_Nazwa = p.podrzędna
     AND podrz.Postacie_ID = p_postac_id

    LEFT JOIN Opanowane nadrz
      ON nadrz.Umiejętności_Nazwa = p.wymagana_nadrzędna
     AND nadrz.Postacie_ID = p_postac_id

    WHERE
        nadrz.poziom IS NULL
        OR
        nadrz.poziom < podrz.poziom + p.minimalny_poziom

    LIMIT 1;

    IF FOUND THEN

        IF naruszenie.poziom_nadrzednej IS NULL THEN

            RAISE EXCEPTION
                'Postać % posiada umiejętność "%", ale nie posiada wymaganej umiejętności nadrzędnej "%".',
                p_postac_id,
                naruszenie.podrzędna,
                naruszenie.wymagana_nadrzędna;

        ELSE

            RAISE EXCEPTION
                'Postać % posiada umiejętność "%" na poziomie %, lecz umiejętność nadrzędna "%" ma poziom %, a wymagany jest co najmniej %.',
                p_postac_id,
                naruszenie.podrzędna,
                naruszenie.poziom_podrzednej,
                naruszenie.wymagana_nadrzędna,
                naruszenie.poziom_nadrzednej,
                naruszenie.poziom_podrzednej + naruszenie.minimalny_poziom;

        END IF;

    END IF;

END;
$$
LANGUAGE plpgsql;
----- funkcja pośrednia
CREATE OR REPLACE FUNCTION trg_sprawdz_zaleznosci_postaci()
RETURNS TRIGGER
AS
$$
BEGIN

    PERFORM sprawdz_zaleznosci_postaci(
        COALESCE(NEW.Postacie_ID, OLD.Postacie_ID)
    );

    RETURN NULL;
    --RETURN COALESCE(NEW, OLD);
END;
$$
LANGUAGE plpgsql;
---trigger
CREATE TRIGGER trg_opanowane_spojnosc
AFTER INSERT OR UPDATE OR DELETE
ON Opanowane
FOR EACH ROW
EXECUTE FUNCTION trg_sprawdz_zaleznosci_postaci();


-- ciąg rang
CREATE OR REPLACE FUNCTION check_ranga_łańcuch()
RETURNS TRIGGER AS $$
DECLARE
    current_class TEXT;
    error_msg TEXT;
BEGIN
    IF TG_OP = 'DELETE' THEN
        current_class := OLD.Klasa_nazwa;
    ELSE
        current_class := NEW.Klasa_nazwa;
    END IF;

    IF current_class IS NULL THEN
        RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
    END IF;

    -- Sprawdź brakujące następniki
    IF EXISTS (
        SELECT 1 FROM Rangi_klasowe r
        WHERE r.Klasa_nazwa = current_class
          AND r.Nastepna_ranga IS NOT NULL
          AND NOT EXISTS (
              SELECT 1 FROM Rangi_klasowe next_r 
              WHERE next_r.Nazwa = r.Nastepna_ranga 
                AND next_r.Klasa_nazwa = current_class
          )
    ) THEN
        RAISE EXCEPTION 'BŁĄD SPÓJNOŚCI: Istnieje ranga z nieistniejącym następnikiem w klasie "%".', current_class;
    END IF;

    -- Sprawdź brak poprzedników
    IF EXISTS (
        SELECT 1 FROM Rangi_klasowe r
        WHERE r.Klasa_nazwa = current_class
          AND r.Poprzednia_ranga IS NOT NULL
          AND NOT EXISTS (
              SELECT 1 FROM Rangi_klasowe prev_r 
              WHERE prev_r.Nazwa = r.Poprzednia_ranga 
                AND prev_r.Klasa_nazwa = current_class
          )
    ) THEN
        RAISE EXCEPTION 'BŁĄD SPÓJNOŚCI: Istnieje ranga z nieistniejącym poprzednikiem w klasie "%".', current_class;
    END IF;

    -- Sprawdź spójność (A -> B, ale B nie wskazuje na A)
    IF EXISTS (
        SELECT 1 FROM Rangi_klasowe r
        JOIN Rangi_klasowe next_r ON r.Nastepna_ranga = next_r.Nazwa
        WHERE r.Klasa_nazwa = current_class
          AND next_r.Klasa_nazwa = current_class
          AND (next_r.Poprzednia_ranga IS NULL OR next_r.Poprzednia_ranga != r.Nazwa)
    ) THEN
        RAISE EXCEPTION 'BŁĄD SPÓJNOŚCI: Niedopasowane linki w klasie "%".', current_class;
    END IF;

    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_check_ranga_łańcuch
AFTER INSERT OR UPDATE OR DELETE ON Rangi_klasowe
FOR EACH ROW
EXECUTE FUNCTION check_ranga_łańcuch();

CREATE OR REPLACE FUNCTION sprawdz_liczbe_aktywnych_klas()
RETURNS trigger AS
$$
DECLARE
    liczba_aktywnych INTEGER;
BEGIN
    -- Interesują nas tylko rekordy ustawiane jako aktywne
    IF NEW.aktywna IS DISTINCT FROM TRUE THEN
        RETURN NEW;
    END IF;

    SELECT COUNT(*)
    INTO liczba_aktywnych
    FROM klasa_postaci
    WHERE Postacie_ID = NEW.Postacie_ID
      AND aktywna = TRUE
      AND Klasa_nazwa <> NEW.Klasa_nazwa;

    IF liczba_aktywnych >= 2 THEN
        RAISE EXCEPTION
            'Postać % może mieć maksymalnie dwie aktywne klasy.',
            NEW.Postacie_ID;
    END IF;

    RETURN NEW;
END;
$$
LANGUAGE plpgsql;
CREATE TRIGGER trg_2_aktywne_klasy
BEFORE INSERT OR UPDATE OF aktywna
ON klasa_postaci
FOR EACH ROW
EXECUTE FUNCTION sprawdz_liczbe_aktywnych_klas();


-- trigger rang klas postaci
---funkcja sprawdzająca i  aktualizująca
CREATE OR REPLACE FUNCTION sprawdz_ranga_postaci()
RETURNS trigger
LANGUAGE plpgsql
AS
$$
DECLARE
    nowa_ranga varchar;
BEGIN

    SELECT rk.Nazwa
    INTO nowa_ranga
    FROM Rangi_klasowe rk
    WHERE rk.Klasa_nazwa = NEW.Klasa_nazwa
      AND rk.minimalne_punkty_klasowe <=
            NEW.ilość_punktów_klasowych
          + NEW.ilość_punktów_klasowych_z_cech
    ORDER BY rk.minimalne_punkty_klasowe DESC
    LIMIT 1;

    IF FOUND THEN
        NEW.Rangi_klasowe_Nazwa := nowa_ranga;
    END IF;

    RETURN NEW;
END;
$$;
--- triggery
CREATE TRIGGER trg_ranga_postaci
BEFORE INSERT OR UPDATE OF
    ilość_punktów_klasowych,
    ilość_punktów_klasowych_z_cech
ON klasa_postaci
FOR EACH ROW
EXECUTE FUNCTION sprawdz_ranga_postaci();

-- triggery punktów klasowych z cech

---funkcja obliczająca nową wartość:
CREATE OR REPLACE FUNCTION oblicz_punkty_klasowe_z_cech
(
    p_postac integer,
    p_klasa varchar
)
RETURNS integer
LANGUAGE plpgsql
AS
$$
DECLARE
    suma_poziom1 integer;
    suma_awansow integer;
BEGIN
    SELECT
        (
            CASE WHEN 'Siła' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Siła_poziom_1 ELSE 0 END
          + CASE WHEN 'Wytrzymałość' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Wytrzymałość_poziom_1 ELSE 0 END
          + CASE WHEN 'Kondycja' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Kondycja_poziom_1 ELSE 0 END
          + CASE WHEN 'Zręczność' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Zręczność_poziom_1 ELSE 0 END
          + CASE WHEN 'Zwinność' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Zwinność_poziom_1 ELSE 0 END

          + CASE WHEN 'Mądrość' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Mądrość_poziom_1 ELSE 0 END
          + CASE WHEN 'Inteligencja' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Inteligencja_poziom_1 ELSE 0 END
          + CASE WHEN 'Charyzma' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Charyzma_poziom_1 ELSE 0 END
          + CASE WHEN 'Pobożność' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Pobożność_poziom_1 ELSE 0 END
          + CASE WHEN 'Wola' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Wola_poziom_1 ELSE 0 END
        ),

        (
            CASE WHEN 'Siła' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Siła_z_awansów ELSE 0 END
          + CASE WHEN 'Wytrzymałość' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Wytrzymałość_z_awansów ELSE 0 END
          + CASE WHEN 'Kondycja' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Kondycja_z_awansów ELSE 0 END
          + CASE WHEN 'Zręczność' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Zręczność_z_awansów ELSE 0 END
          + CASE WHEN 'Zwinność' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Zwinność_z_awansów ELSE 0 END

          + CASE WHEN 'Mądrość' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Mądrość_z_awansów ELSE 0 END
          + CASE WHEN 'Inteligencja' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Inteligencja_z_awansów ELSE 0 END
          + CASE WHEN 'Charyzma' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Charyzma_z_awansów ELSE 0 END
          + CASE WHEN 'Pobożność' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Pobożność_z_awansów ELSE 0 END
          + CASE WHEN 'Wola' IN (k.premiowana_cecha1, k.premiowana_cecha2, k.premiowana_cecha3)
                 THEN p.Wola_z_awansów ELSE 0 END
        )

    INTO
        suma_poziom1,
        suma_awansow
    FROM Postacie p
    JOIN Klasa_postaci kp
        ON kp.Postacie_ID=p.ID_postaci
        AND kp.Klasa_nazwa=p_klasa
    JOIN Klasy k
        ON k.Nazwa=kp.Klasa_nazwa
    WHERE p.ID_postaci=p_postac;
    RETURN
          suma_awansow
        + floor((suma_poziom1+suma_awansow)/10.0);
END;
$$;

---- łańcuch wywoływany przez trigger postaci:
-----aktualizujacyjna
CREATE OR REPLACE FUNCTION aktualizuj_punkty_klasowe_z_cech_postaci
(
    p_postac integer
)
RETURNS void
LANGUAGE plpgsql
AS
$$
BEGIN
    UPDATE klasa_postaci kp
    SET ilość_punktów_klasowych_z_cech =
        oblicz_punkty_klasowe_z_cech
        (
            kp.Postacie_ID,
            kp.Klasa_nazwa
        )
    WHERE kp.Postacie_ID=p_postac;
END;
$$;
-----funkcja triggera postaci
CREATE OR REPLACE FUNCTION trg_postacie_wyzwol_przeliczenie_pkt_klasowych_postaci()
RETURNS trigger
LANGUAGE plpgsql
AS
$$
BEGIN
    PERFORM aktualizuj_punkty_klasowe_z_cech_postaci(NEW.ID_postaci);
    RETURN NEW;
END;
$$;
-----trigger postaci po modyfikacji cech bazowych
CREATE TRIGGER trg_pkt_klasowe_postaci
    AFTER UPDATE OF
        Siła_poziom_1,
        Wytrzymałość_poziom_1,
        Kondycja_poziom_1,
        Zręczność_poziom_1,
        Zwinność_poziom_1,
        Mądrość_poziom_1,
        Inteligencja_poziom_1,
        Charyzma_poziom_1,
        Pobożność_poziom_1,
        Wola_poziom_1,

        Siła_z_awansów,
        Wytrzymałość_z_awansów,
        Kondycja_z_awansów,
        Zręczność_z_awansów,
        Zwinność_z_awansów,
        Mądrość_z_awansów,
        Inteligencja_z_awansów,
        Charyzma_z_awansów,
        Pobożność_z_awansów,
        Wola_z_awansów
    ON Postacie
    FOR EACH ROW
    EXECUTE FUNCTION trg_postacie_wyzwol_przeliczenie_pkt_klasowych_postaci();--aktualizuj_punkty_klasowe_z_cech_postaci?

---- łańcuch wywoływany przez trigger klasy_postaci:
