CREATE OR REPLACE FUNCTION aktualizuj_punkty_klasowe_z_cech_klasy_postaci
(
    p_postac integer,
    kp_klasa varchar
)
RETURNS void
LANGUAGE plpgsql
AS
$$
BEGIN
    UPDATE klasa_postaci kp
