-- ==========================================
-- 5. Kontrola 1 - Wyświetlanie struktur bazy danych
-- ==========================================

SELECT table_schema, table_name
FROM information_schema.TABLES
Where table_schema='public'

SELECT table_schema, table_name, column_name, column_default, data_type
FROM information_schema.COLUMNS
Where table_schema='public'
ORDER BY table_name

--ograniczenia
SELECT t1.constraint_name, t1.constraint_type, t2.check_clause
FROM information_schema.table_constraints t1 LEFT JOIN information_schema.check_constraints t2
ON t1.constraint_name = t2.constraint_name
AND t1.constraint_schema = t2.constraint_schema
Where table_schema='public'
ORDER BY constraint_name;

--ograniczenia szczegóły2
SELECT
    nsp.nspname AS schemat,
    rel.relname AS tabela,
    con.conname AS nazwa_ograniczenia,
    CASE con.contype
        WHEN 'p' THEN 'PRIMARY KEY'
        WHEN 'f' THEN 'FOREIGN KEY'
        WHEN 'u' THEN 'UNIQUE'
        WHEN 'c' THEN 'CHECK'
        WHEN 'n' THEN 'NOT NULL'
        ELSE con.contype
    END AS typ_ograniczenia,
    pg_get_constraintdef(con.oid) AS definicja -- Czytelna definicja (np. "CHECK ((x > 0))")
FROM pg_catalog.pg_constraint con
JOIN pg_catalog.pg_class rel ON rel.oid = con.conrelid
JOIN pg_catalog.pg_namespace nsp ON nsp.oid = connamespace
WHERE nsp.nspname = 'public' -- Opcjonalnie: ogranicz do schematu public
ORDER BY schemat, tabela, nazwa_ograniczenia;


-- ==========================================
-- 6. Widoki i pokrewne funkcje
-- ==========================================

--RASY
---Cechy Bazowe
CREATE OR REPLACE VIEW Cechy_Rasowe AS
WITH r AS (
    SELECT 
        Nazwa,
        MAGICZNOŚĆ,
        Mądrość_OCENA,
        Inteligencja_OCENA,
        Wola_OCENA,
        Pobożność_OCENA,
        Charyzma_OCENA,
        Wytrzymałość_OCENA,
        Siła_OCENA,
        Zręczność_OCENA,
        Zwinność_OCENA,
        Kondycja_OCENA,
        wiek_starości,
        CASE
            WHEN Rozumność THEN 10
            WHEN Rozumność IS NULL THEN 5
            ELSE 0 END
        AS premia
    FROM Rasy
)
SELECT 
    Nazwa,
    1+Mądrość_OCENA + MAGICZNOŚĆ + premia       AS Mądrość,
    1+Inteligencja_OCENA + MAGICZNOŚĆ + premia  AS Inteligencja,
    1+Wola_OCENA + premia                       AS Wola,
    1+Pobożność_OCENA + premia                  AS Pobożność,
    1+Charyzma_OCENA + premia                   AS Charyzma,
    1+Wytrzymałość_OCENA                        AS Wytrzymałość,
    1+Siła_OCENA                                AS Siła,
    1+Zręczność_OCENA                           AS Zręczność,
    1+Zwinność_OCENA                            AS Zwinność,
    1+Kondycja_OCENA                            AS Kondycja,
    wiek_starości
FROM r;
---Statystyki Bazowe
-----Życie	Mana	Energia
CREATE OR REPLACE VIEW Statystyki_Rasowe AS
SELECT
    RASY.Nazwa,
    100+Mądrość*5             AS Mana,
    Inteligencja*2            AS Regeneracja_many,
    50+Wytrzymałość*5         AS Życie,
    100+Kondycja*5            AS Energia,
    Kondycja/10.0             AS Regeneracja_Energii,
    Round(inteligencja/5)     AS Koszt_Energetyczny_Regeneracji_many,
    --alternatywnie Round(Regeneracja_many/10) (z dołożonym podzapytaniem)
    Pancerz_Ogólny,
    Pancerz_miękki,
    Pancerz_twardy,
    Ochrona_przed_zimnem
FROM Cechy_Rasowe INNER JOIN RASY ON Cechy_Rasowe.Nazwa = RASY.Nazwa;

--POSTACIE I

---Cechy Bazowe
CREATE OR REPLACE VIEW Postacie_Cechy_Bazowe AS
WITH r AS (
    SELECT *,
        CASE
            WHEN Postacie.Wiek-Cechy_Rasowe.wiek_starości>0 THEN ROUND((Postacie.Wiek-Cechy_Rasowe.wiek_starości)/3)
            ELSE 0--ROUND((Postacie.Wiek-Cechy_Rasowe.wiek_starości)/10)
        END AS Mod_wiekowy_starczy,
        CASE
            WHEN Postacie.Wiek-Cechy_Rasowe.wiek_starości<0 THEN ROUND((Postacie.Wiek)/20)
            ELSE 0
        END AS Mod_wiekowy_młodzieńczy
    FROM Cechy_Rasowe INNER JOIN POSTACIE ON Cechy_Rasowe.Nazwa=Postacie.Rasy_Nazwa--!INDEKSUJ!
)
SELECT 
    ID_postaci,
    Imię,
    Nazwisko,
    Mądrość_poziom_1+Mądrość_z_awansów+Mądrość+COALESCE(Mod_wiekowy_starczy+Mod_wiekowy_młodzieńczy,0)  AS Mądrość,
    Inteligencja_poziom_1 + Inteligencja_z_awansów + Inteligencja                                       AS Inteligencja,
    Wola_poziom_1 + Wola_z_awansów + Wola                                                               AS Wola,
    Pobożność_poziom_1 + Pobożność_z_awansów + Pobożność                                                AS Pobożność,
    Charyzma_poziom_1 + Charyzma_z_awansów + Charyzma                                                   AS Charyzma,
    Wytrzymałość_poziom_1 + Wytrzymałość_z_awansów + Wytrzymałość                                       AS Wytrzymałość,
    Siła_poziom_1 + Siła_z_awansów + Siła                                                               AS Siła,
    Zręczność_poziom_1 + Zręczność_z_awansów + Zręczność                                                AS Zręczność,
    Zwinność_poziom_1 + Zwinność_z_awansów + Zwinność                                                   AS Zwinność,
    Kondycja_poziom_1 + Kondycja_z_awansów + Kondycja - COALESCE(Mod_wiekowy_starczy,0)                 AS Kondycja,
    Rasy_Nazwa                                                                                          AS Nazwa_Rasy 
FROM r;

---Statystyki Bazowe
-----Życie	Mana	Energia
CREATE OR REPLACE VIEW Statystyki_Bazowe_Postaci AS
SELECT
    ID_postaci,
    Imię,
    Nazwisko,
    100+Mądrość*5             AS Mana,
    Inteligencja*2            AS Regeneracja_many,
    50+Wytrzymałość*5         AS Życie,
    100+Kondycja*5            AS Energia,
    Kondycja/10.0               AS Regeneracja_Energii,
    Round(inteligencja/5)     AS Koszt_Energetyczny_Regeneracji_many,
    --alternatywnie Round(Regeneracja_many/10) (z dołożonym podzapytaniem)
    Pancerz_Ogólny,
    Pancerz_miękki,
    Pancerz_twardy,
    Ochrona_przed_zimnem
FROM Postacie_Cechy_Bazowe INNER JOIN Rasy ON Postacie_Cechy_Bazowe.Nazwa_Rasy=RASY.Nazwa--?INDEKSUJ?;


--KLASY I
---bonusy do cech z klas postaci

----widok głównie techniczny
----widok szczegółowo pokazuje dla każdej postaci(ID) liczbę bonusowych pkt. cech jaką może mieć na poziom,
---- z każdej z klas, które rozwija
CREATE OR REPLACE VIEW bonusy_klasowe_na_poziom AS
WITH bonusy_z_rang AS
(
    SELECT
        (bonus_do_cech_wartość/bonus_do_cech_co_poziomów) AS bonus_na_poziom,
        Klasa_nazwa,
        Nazwa
    FROM Rangi_klasowe
)
SELECT 
    Postacie_ID,
    klasa_postaci.Klasa_Nazwa AS Nazwa_Klasy,
    CASE
        WHEN 'Mądrość' IN(premiowana_cecha1, premiowana_cecha2, premiowana_cecha3)--(SELECT Cecha FROM Klasy_Cechy) 
        THEN bonus_na_poziom
        ELSE 0
    END AS Mądrość_na_poziom,
    CASE
        WHEN 'Inteligencja' IN(premiowana_cecha1, premiowana_cecha2, premiowana_cecha3)--(SELECT Cecha FROM Klasy_Cechy) 
        THEN bonus_na_poziom
        ELSE 0
    END AS Inteligencja_na_poziom,
    CASE
        WHEN 'Wola' IN(premiowana_cecha1, premiowana_cecha2, premiowana_cecha3)--(SELECT Cecha FROM Klasy_Cechy) 
        THEN bonus_na_poziom
        ELSE 0
    END AS Wola_na_poziom,
    CASE
        WHEN 'Pobożność' IN(premiowana_cecha1, premiowana_cecha2, premiowana_cecha3)--(SELECT Cecha FROM Klasy_Cechy) 
        THEN bonus_na_poziom
        ELSE 0
    END AS Pobożność_na_poziom,
    CASE
        WHEN 'Charyzma' IN(premiowana_cecha1, premiowana_cecha2, premiowana_cecha3)--(SELECT Cecha FROM Klasy_Cechy) 
        THEN bonus_na_poziom
        ELSE 0
    END AS Charyzma_na_poziom,
    CASE
        WHEN 'Wytrzymałość' IN(premiowana_cecha1, premiowana_cecha2, premiowana_cecha3)--(SELECT Cecha FROM Klasy_Cechy) 
        THEN bonus_na_poziom
        ELSE 0
    END AS Wytrzymałość_na_poziom,
    CASE
        WHEN 'Siła' IN(premiowana_cecha1, premiowana_cecha2, premiowana_cecha3)--(SELECT Cecha FROM Klasy_Cechy) 
        THEN bonus_na_poziom
        ELSE 0
    END AS Siła_na_poziom,
    CASE
        WHEN 'Zręczność' IN(premiowana_cecha1, premiowana_cecha2, premiowana_cecha3)--(SELECT Cecha FROM Klasy_Cechy) 
        THEN bonus_na_poziom
        ELSE 0
    END AS Zręczność_na_poziom,
    CASE
        WHEN 'Zwinność' IN(premiowana_cecha1, premiowana_cecha2, premiowana_cecha3)--(SELECT Cecha FROM Klasy_Cechy) 
        THEN bonus_na_poziom
        ELSE 0
    END AS Zwinność_na_poziom,
    CASE
        WHEN 'Kondycja' IN(premiowana_cecha1, premiowana_cecha2, premiowana_cecha3)--(SELECT Cecha FROM Klasy_Cechy) 
        THEN bonus_na_poziom
        ELSE 0
    END AS Kondycja_na_poziom,
    aktywna
FROM klasa_postaci
    INNER JOIN bonusy_z_rang 
        ON klasa_postaci.Klasa_nazwa = bonusy_z_rang.Klasa_nazwa
            AND klasa_postaci.Rangi_klasowe_Nazwa = bonusy_z_rang.Nazwa
    INNER JOIN KLASY--Klasy_Cechy
        ON klasa_postaci.Klasa_Nazwa=Klasy.nazwa
--ORDER BY ID_postaci
;


----widok szczegółowo pokazuje dla każdej postaci liczbę bonusowych pkt. cech jaką może mieć z każdej z klas,
----które rozwija
-----zaokrąglenia następują dopiero po sumowaniu[rozważyć zmianę inner Join na left join]
CREATE OR REPLACE VIEW bonusy_klasowe AS
SELECT 
    ID_postaci,
    Imię,
    NAZWISKO,
    Nazwa_Klasy,
    poziom*Mądrość_na_poziom AS Mądrość,
    poziom*Inteligencja_na_poziom AS Inteligencja,
    poziom*Wola_na_poziom AS Wola,
    poziom*Pobożność_na_poziom AS Pobożność,
    poziom*Charyzma_na_poziom AS Charyzma,
    poziom*Wytrzymałość_na_poziom AS Wytrzymałość,
    poziom*Siła_na_poziom AS Siła,
    poziom*Zręczność_na_poziom AS Zręczność,
    poziom*Zwinność_na_poziom AS Zwinność,
    poziom*Kondycja_na_poziom AS Kondycja,
    aktywna
FROM POSTACIE
    INNER JOIN bonusy_klasowe_na_poziom
        ON POSTACIE.ID_postaci=bonusy_klasowe_na_poziom.Postacie_ID


----Podsumowanie bonusów na poziom dla poszczególnych postaci
CREATE OR REPLACE VIEW bonusy_klasowe_postaci_na_poziom AS
WITH Obliczenia AS
(--FILTER (WHERE aktywna)
    SELECT 
    Postacie_ID,
    SUM(Mądrość_na_poziom) AS Mądrość_na_poziom,
    SUM(Inteligencja_na_poziom) AS Inteligencja_na_poziom,
    SUM(Wola_na_poziom) AS Wola_na_poziom,
    SUM(Pobożność_na_poziom) AS Pobożność_na_poziom,
    SUM(Charyzma_na_poziom) AS Charyzma_na_poziom,
    SUM(Wytrzymałość_na_poziom) AS Wytrzymałość_na_poziom,
    SUM(Siła_na_poziom) AS Siła_na_poziom,
    SUM(Zręczność_na_poziom) AS Zręczność_na_poziom,
    SUM(Zwinność_na_poziom) AS Zwinność_na_poziom,
    SUM(Kondycja_na_poziom) AS Kondycja_na_poziom
    FROM bonusy_klasowe_na_poziom
    WHERE aktywna=TRUE
    GROUP BY Postacie_ID
)
SELECT 
    ID_postaci,
    Imię,
    NAZWISKO,
    Mądrość_na_poziom,
    Inteligencja_na_poziom,
    Wola_na_poziom,
    Pobożność_na_poziom,
    Charyzma_na_poziom,
    Wytrzymałość_na_poziom,
    Siła_na_poziom,
    Zręczność_na_poziom,
    Zwinność_na_poziom,
    Kondycja_na_poziom
FROM Obliczenia o JOIN POSTACIE p ON o.Postacie_ID = p.ID_postaci;

CREATE OR REPLACE VIEW bonusy_klasowe_postaci AS
SELECT 
    p.ID_postaci,
    p.Imię,
    p.NAZWISKO,
    floor(poziom*Mądrość_na_poziom)        AS Mądrość,
    floor(poziom*Inteligencja_na_poziom)   AS Inteligencja,
    floor(poziom*Wola_na_poziom)           AS Wola,
    floor(poziom*Pobożność_na_poziom)      AS Pobożność,
    floor(poziom*Charyzma_na_poziom)       AS Charyzma,
    floor(poziom*Wytrzymałość_na_poziom)   AS Wytrzymałość,
    floor(poziom*Siła_na_poziom)           AS Siła,
    floor(poziom*Zręczność_na_poziom)      AS Zręczność,
    floor(poziom*Zwinność_na_poziom)       AS Zwinność,
    floor(poziom*Kondycja_na_poziom)       AS Kondycja
FROM bonusy_klasowe_postaci_na_poziom b JOIN POSTACIE p ON b.ID_postaci = p.ID_postaci;

--POSTACIE II
---kontrola poprawności przydziału punktów cech z awansów i klasowych 

----ilości punktów_cech_z_klas które mogą mieć poszczególne postacie przy wybraniu danych klas jako aktywne 
CREATE OR REPLACE VIEW punkty_cech_z_klas AS
SELECT
    p.ID_postaci,
    p.Imię,
    p.Nazwisko,
    r.punkty_cech_na_awans,
    k.aktywna,
    k.Klasa_Nazwa,
    -- elementy techniczne
    ---- Przypisz numer wiersza w ramach każdej postaci, sortując od największej wartości
    ROW_NUMBER() OVER
    (
        PARTITION BY p.ID_postaci 
        ORDER BY r.punkty_cech_na_awans DESC
    ) AS rn,
    p.poziom
FROM Postacie p 
    INNER JOIN klasa_postaci k ON p.ID_postaci = k.Postacie_ID
    INNER JOIN Rangi_klasowe r ON k.Klasa_Nazwa = r.Klasa_Nazwa
        AND k.Rangi_klasowe_Nazwa=r.Nazwa;

--wybór których dostępnych klas dałby postaci obecnie sumarycznie najwięcej punktów
CREATE OR REPLACE VIEW maksymalne_punkty_cech_z_klas AS
SELECT
    ID_postaci,
    Imię,
    Nazwisko,
    (poziom-1)*SUM(punkty_cech_na_awans) AS maksymalne_punkty_klasowe,
    STRING_AGG(Klasa_Nazwa, ', ') AS przykładowe_potrzebne_aktywne_klasy
FROM punkty_cech_z_klas punkty
WHERE rn <= 2  -- Wybierz tylko wiersze z rangą 1 lub 2 dla każdej postaci
GROUP BY ID_postaci, Imię, Nazwisko, poziom;
-----tu ____________\  /
--                   \/
CREATE OR REPLACE VIEW kontrola_cech_postaci AS
WITH Sumy as 
(
    SELECT
        ID_postaci,
        Imię,
        Nazwisko,
        ----
        Poziom,   
        (
            Siła_poziom_1 
            + Wytrzymałość_poziom_1
            + Kondycja_poziom_1
            + Zręczność_poziom_1
            + Zwinność_poziom_1
            + Mądrość_poziom_1
            + Inteligencja_poziom_1
            + Charyzma_poziom_1
            + Pobożność_poziom_1
            + Wola_poziom_1
        ) AS SUMA_poziom_1,
        (
            Siła_z_awansów 
            + Wytrzymałość_z_awansów
            + Kondycja_z_awansów
            + Zręczność_z_awansów
            + Zwinność_z_awansów
            + Mądrość_z_awansów
            + Inteligencja_z_awansów
            + Charyzma_z_awansów
            + Pobożność_z_awansów
            + Wola_z_awansów
        ) AS SUMA_z_awansów,
        10*(poziom-1) AS punkty_cech_z_awansów,
        (
            Siła_klasowa 
            + Wytrzymałość_klasowa
            + Kondycja_klasowa
            + Zręczność_klasowa
            + Zwinność_klasowa
            + Mądrość_klasowa
            + Inteligencja_klasowa
            + Charyzma_klasowa
            + Pobożność_klasowa
            + Wola_klasowa
        ) AS SUMA_klasowa
        FROM Postacie 
)
SELECT 
    s.ID_postaci,
    s.Imię,
    s.Nazwisko,
    ----
    s.SUMA_poziom_1,
    50 AS oczekiwana_suma_poziom_1,
    50-SUMA_poziom_1 AS do_przydzielenia_poziom_1,
    ------
    s.Poziom,
    s.SUMA_z_awansów,
    s.punkty_cech_z_awansów AS oczekiwana_suma_z_awansów,
    s.punkty_cech_z_awansów-s.SUMA_z_awansów AS do_przydzielenia_z_awansów,
    ----
    s.SUMA_klasowa,
    m.maksymalne_punkty_klasowe,
    m.przykładowe_potrzebne_aktywne_klasy,
    CASE
        WHEN m.maksymalne_punkty_klasowe<s.SUMA_klasowa THEN 'wykryto ewidentny błąd'
        WHEN m.maksymalne_punkty_klasowe=s.SUMA_klasowa THEN 'wykryto anomalię - zbadaj przyczynę'
        ELSE 'nie wykryto poważnych błędów'
    END AS czy_wykryto_ewidentny_błąd
FROM Sumy s INNER JOIN maksymalne_punkty_cech_z_klas m ON s.ID_postaci=m.ID_postaci;

---Cechy Naturalne(Bazowe+Klasowe)
CREATE OR REPLACE VIEW Postacie_Cechy_Naturalne AS
WITH r AS (
    SELECT *,
        CASE
            WHEN Postacie.Wiek-Cechy_Rasowe.wiek_starości>0 THEN ROUND((Postacie.Wiek-Cechy_Rasowe.wiek_starości)/3)
            ELSE 0--ROUND((Postacie.Wiek-Cechy_Rasowe.wiek_starości)/10)
        END AS Mod_wiekowy_starczy,
        CASE
            WHEN Postacie.Wiek-Cechy_Rasowe.wiek_starości<0 THEN ROUND((Postacie.Wiek)/20)
            ELSE 0
        END AS Mod_wiekowy_młodzieńczy
    FROM Cechy_Rasowe INNER JOIN POSTACIE ON Cechy_Rasowe.Nazwa=Postacie.Rasy_Nazwa--!INDEKSUJ!
)
SELECT 
    r.ID_postaci,
    r.Imię,
    r.Nazwisko,
    Mądrość_poziom_1+Mądrość_z_awansów+Mądrość_klasowa+r.Mądrość+COALESCE(b.Mądrość,0)+COALESCE(Mod_wiekowy_starczy+Mod_wiekowy_młodzieńczy,0)      AS Mądrość,
    Inteligencja_poziom_1 + Inteligencja_z_awansów + Inteligencja_klasowa + r.Inteligencja + COALESCE(b.Inteligencja,0)       AS Inteligencja,
    Wola_poziom_1 + Wola_z_awansów + Wola_klasowa + r.Wola + COALESCE(b.Wola,0)                                               AS Wola,
    Pobożność_poziom_1 + Pobożność_z_awansów + Pobożność_klasowa + r.Pobożność + COALESCE(b.Pobożność,0)                      AS Pobożność,
    Charyzma_poziom_1 + Charyzma_z_awansów + Charyzma_klasowa + r.Charyzma + COALESCE(b.Charyzma,0)                           AS Charyzma,
    Wytrzymałość_poziom_1 + Wytrzymałość_z_awansów + Wytrzymałość_klasowa + r.Wytrzymałość + COALESCE(b.Wytrzymałość,0)       AS Wytrzymałość,
    Siła_poziom_1 + Siła_z_awansów + Siła_klasowa + r.Siła + COALESCE(b.Siła,0)                                               AS Siła,
    Zręczność_poziom_1 + Zręczność_z_awansów + Zręczność_klasowa + r.Zręczność + COALESCE(b.Zręczność,0)                      AS Zręczność,
    Zwinność_poziom_1 + Zwinność_z_awansów + Zwinność_klasowa + r.Zwinność + COALESCE(b.Zwinność,0)                           AS Zwinność,
    Kondycja_poziom_1 + Kondycja_z_awansów + Kondycja_klasowa + r.Kondycja + COALESCE(b.Kondycja,0) - COALESCE(Mod_wiekowy_starczy,0) AS Kondycja,
    Rasy_Nazwa                                                                                                AS Nazwa_Rasy 
FROM r LEFT JOIN bonusy_klasowe_postaci b ON r.ID_postaci=b.ID_postaci 

---Statystyki Naturalne(Bazowe+Klasowe)
---Statystyki Bazowe
-----Życie	Mana	Energia
CREATE OR REPLACE VIEW Statystyki_Naturalne_Postaci AS
SELECT
    ID_postaci,
    Imię,
    Nazwisko,
    100+Mądrość*5             AS Mana,
    Inteligencja*2            AS Regeneracja_many,
    50+Wytrzymałość*5         AS Życie,
    100+Kondycja*5            AS Energia,
    Kondycja/10.0               AS Regeneracja_Energii,
    Round(inteligencja/5)     AS Koszt_Energetyczny_Regeneracji_many,
    --alternatywnie Round(Regeneracja_many/10) (z dołożonym podzapytaniem)
    Pancerz_Ogólny,
    Pancerz_miękki,
    Pancerz_twardy,
    Ochrona_przed_zimnem
FROM Postacie_Cechy_Naturalne INNER JOIN Rasy ON Postacie_Cechy_Naturalne.Nazwa_Rasy=RASY.Nazwa--?INDEKSUJ?;


--PRZEDMIOTY I
---na co stać postać na_co_stać_postać
CREATE OR REPLACE VIEW Budżety AS
SELECT
    ID_postaci,
    Imię,
    Nazwisko,
    SUM(Pi.Ilość*W.Przelicznik_na_główną_walutę) AS Budżet
FROM Waluty W
    INNER JOIN Pieniądze Pi ON W.nazwa=Pi.Waluta
    INNER JOIN Postacie Pos ON Pi.Postacie_ID=Pos.ID_postaci
GROUP BY ID_postaci,    Imię,    Nazwisko;

CREATE OR REPLACE VIEW na_co_stać_postać AS
SELECT
    ID_postaci,
    Imię,
    Nazwisko,
    Budżet,
    Przed_cena_domyślna,
    Przed_Nazwa
FROM Budżety B JOIN Przedmioty P ON B.Budżet>=P.Przed_cena_domyślna;

---bonusy z aktywnych przedmiotów
CREATE OR REPLACE VIEW bonusy_z_przedmiotów AS
SELECT
--
    Prz.Przed_Nazwa,
    Pos.ID_postaci,
    Pos.Imię,
    Pos.Nazwisko,
    COALESCE(Broń_Bonus_do_mądrości,0) + COALESCE(Pancerz_Bonus_do_mądrości,0) AS Mądrość,
    COALESCE(Broń_Bonus_do_inteligencji,0) + COALESCE(Pancerz_Bonus_do_inteligencji,0) AS Inteligencja,
    COALESCE(Broń_Bonus_do_woli,0) + COALESCE(Pancerz_Bonus_do_woli,0) AS Wola,
    COALESCE(Broń_Bonus_do_pobożności,0) + COALESCE(Pancerz_Bonus_do_pobożności,0) AS Pobożność,
    COALESCE(Broń_Bonus_do_charyzmy,0) + COALESCE(Pancerz_Bonus_do_charyzmy,0) AS Charyzma,
    COALESCE(Broń_Bonus_do_wytrzymałości,0) + COALESCE(Pancerz_Bonus_do_wytrzymałości,0) AS Wytrzymałość,
    COALESCE(Broń_Bonus_do_siły,0) + COALESCE(Pancerz_Bonus_do_siły,0) AS Siła,--Bonus_do_siły,
    COALESCE(Broń_Bonus_do_zręczności,0) + COALESCE(Pancerz_Bonus_do_zręczności,0) AS Zręczność,
    COALESCE(Broń_Bonus_do_zwinności,0) + COALESCE(Pancerz_Bonus_do_zwinności,0) AS Zwinność,
    COALESCE(Broń_Bonus_do_kondycji,0) + COALESCE(Pancerz_Bonus_do_kondycji,0) AS Kondycja,
    COALESCE(Pis.Pancerz_Pancerz_Ogólny,0) AS Pancerz_Ogólny,
    COALESCE(Pis.Pancerz_Pancerz_Miękki,0) AS Pancerz_miękki,
    COALESCE(Pis.Pancerz_Pancerz_Twardy,0) AS Pancerz_twardy,
    COALESCE(Pis.Pancerz_Ochrona_przed_zimnem,0) AS Ochrona_przed_zimnem,
    jest_noszony
FROM Postacie Pos
    INNER JOIN Egzemplarze_Przedmiotów EP ON Pos.ID_postaci=EP.Postacie_ID
    INNER JOIN Przedmioty Prz ON EP.Przed_Nazwa = Prz.Przed_Nazwa
    LEFT JOIN Bronie B ON Prz.Przed_Nazwa=B.Przedmioty_Przed_Nazwa
    LEFT JOIN Pancerze_i_stroje Pis ON Prz.Przed_Nazwa=Pis.Przedmioty_Przed_Nazwa

CREATE OR REPLACE VIEW bonusy_z_przedmiotów_postaci AS
SELECT
    ID_postaci,
    Imię,
    NAZWISKO,
    SUM(Mądrość) AS Mądrość,
    SUM(Inteligencja) AS Inteligencja,
    SUM(Wola) AS Wola,
    SUM(Pobożność) AS Pobożność,
    SUM(Charyzma) AS Charyzma,
    SUM(Wytrzymałość) AS Wytrzymałość,
    SUM(Siła) AS Siła,
    SUM(Zręczność) AS Zręczność,
    SUM(Zwinność) AS Zwinność,
    SUM(Kondycja) AS Kondycja,
    SUM(Pancerz_Ogólny) AS Pancerz_Ogólny,
    SUM(Pancerz_Miękki) AS Pancerz_Miękki,
    SUM(Pancerz_Twardy) AS Pancerz_Twardy,
    SUM(Ochrona_przed_zimnem) AS Ochrona_przed_zimnem
FROM bonusy_z_przedmiotów  
WHERE jest_noszony
GROUP BY ID_postaci, Imię, NAZWISKO


--Postacie III

---Cechy Efektywne
CREATE OR REPLACE VIEW Postacie_Cechy_Efektywne AS
SELECT 
    PCN.ID_postaci,
    PCN.Imię,
    PCN.Nazwisko,
    PCN.Mądrość + COALESCE(BzP.Mądrość,0)             AS Mądrość,
    PCN.Inteligencja + COALESCE(BzP.Inteligencja,0)   AS Inteligencja,
    PCN.Wola + COALESCE(BzP.Wola,0)                   AS Wola,
    PCN.Pobożność + COALESCE(BzP.Pobożność,0)         AS Pobożność,
    PCN.Charyzma + COALESCE(BzP.Charyzma,0)           AS Charyzma,
    PCN.Wytrzymałość + COALESCE(BzP.Wytrzymałość,0)   AS Wytrzymałość,
    PCN.Siła + COALESCE(BzP.Siła,0)                   AS Siła,
    PCN.Zręczność + COALESCE(BzP.Zręczność,0)         AS Zręczność,
    PCN.Zwinność + COALESCE(BzP.Zwinność,0)           AS Zwinność,
    PCN.Kondycja + COALESCE(BzP.Kondycja,0)           AS Kondycja,
    COALESCE(BzP.Pancerz_Ogólny,0)                    AS Pancerz_Ogólny,
    COALESCE(BzP.Pancerz_Miękki,0)                    AS Pancerz_Miękki,
    COALESCE(BzP.Pancerz_Twardy,0)                    AS Pancerz_Twardy,
    COALESCE(BzP.Ochrona_przed_zimnem,0)              AS Ochrona_przed_zimnem
FROM bonusy_z_przedmiotów_postaci BzP RIGHT JOIN Postacie_Cechy_Naturalne PCN ON BzP.ID_postaci=PCN.ID_postaci

