--UMIEJĘTNOŚCI
--lista umiejętności postaci możliwych do opanowania lub podwyższenia przez postać
---lista umiejętności postaci możliwych do opanowania przez postać
CREATE OR REPLACE VIEW umiejętności_możliwe_do_opanowania AS
SELECT
    p.ID_postaci,
    u.Nazwa AS Nazwa_Umiejętności
FROM Postacie p
    CROSS JOIN Umiejętności u
WHERE 
    NOT EXISTS (
        -- postać jeszcze nie opanowała tej umiejętności
        SELECT 1
        FROM Opanowane o
        WHERE o.Postacie_ID = p.ID_postaci
        AND o.Umiejętności_Nazwa = u.Nazwa
        )
    AND NOT EXISTS (
    -- nie istnieje niespełnione wymaganie nadrzędne
        SELECT 1
        FROM Podległość pod
        WHERE pod.podrzędna = u.Nazwa
        AND NOT EXISTS (
            SELECT 1
            FROM Opanowane o
            WHERE o.Postacie_ID = p.ID_postaci
                AND o.Umiejętności_Nazwa = pod.wymagana_nadrzędna
                AND o.poziom >= pod.minimalny_poziom
      )
)
;

CREATE OR REPLACE VIEW maksymalne_poziomy_umiejętności_postaci AS
SELECT
    p.ID_postaci,
    u.Nazwa AS Nazwa_Umiejętności,
    CASE
        WHEN NOT EXISTS (
            SELECT 1
            FROM Podległość pod
            WHERE pod.podrzędna = u.Nazwa
        )
        THEN TRUE--p.Poziom
        ELSE NOT EXISTS (
            SELECT 1
            FROM Podległość pod
            WHERE pod.podrzędna = u.Nazwa
              AND NOT EXISTS (
                  SELECT 1
                  FROM Opanowane o_nadrz
                  WHERE o_nadrz.Postacie_ID = p.ID_postaci
                    AND o_nadrz.Umiejętności_Nazwa =
                        pod.wymagana_nadrzędna
                    AND o_nadrz.poziom >= pod.minimalny_poziom
              )
        )
    END AS wymagania_spelnione,
    CASE
        WHEN NOT EXISTS (
            SELECT 1
            FROM Podległość pod
            WHERE pod.podrzędna = u.Nazwa
        )
        THEN p.Poziom
        ELSE COALESCE(
            (
                SELECT MIN(
                    o_nadrz.poziom - pod.minimalny_poziom
                )
                FROM Podległość pod
                JOIN Opanowane o_nadrz
                    ON o_nadrz.Umiejętności_Nazwa =
                       pod.wymagana_nadrzędna
                   AND o_nadrz.Postacie_ID = p.ID_postaci
                WHERE pod.podrzędna = u.Nazwa
            ),
            0--czyli nie może być opanowana
        )
    END AS Maksymalny_poziom
FROM Postacie p
    CROSS JOIN Umiejętności u;

CREATE OR REPLACE VIEW umiejętności_możliwe_do_podwyższenia AS
SELECT
    m.ID_postaci,
    m.Nazwa_Umiejętności
FROM maksymalne_poziomy_umiejętności_postaci m
    JOIN Opanowane o
        ON o.Postacie_ID = m.ID_postaci
        AND o.Umiejętności_Nazwa = m.Nazwa_Umiejętności
WHERE o.poziom < m.Maksymalny_poziom;

CREATE OR REPLACE VIEW maksymalne_poziomy_posiadanych_umiejętności AS
SELECT
    m.ID_postaci,
    m.Nazwa_Umiejętności,
    o.poziom AS Obecny_poziom,
    m.Maksymalny_poziom
FROM maksymalne_poziomy_umiejętności_postaci m
    JOIN Opanowane o
        ON o.Postacie_ID = m.ID_postaci
        AND o.Umiejętności_Nazwa = m.Nazwa_Umiejętności;

CREATE OR REPLACE VIEW umiejętności_możliwe_do_awansowania AS
    SELECT
        ID_postaci,
        Nazwa_Umiejętności
    FROM umiejętności_możliwe_do_opanowania
UNION
    SELECT
        ID_postaci,
        Nazwa_Umiejętności
    FROM umiejętności_możliwe_do_podwyższenia;

CREATE OR REPLACE VIEW maksymalne_poziomy_możliwe_do_awansowania AS
SELECT
    m.ID_postaci,
    m.Nazwa_Umiejętności,
    COALESCE(o.poziom, 0) AS Obecny_poziom,
    m.Maksymalny_poziom
FROM maksymalne_poziomy_umiejętności_postaci m
    LEFT JOIN Opanowane o
        ON o.Postacie_ID = m.ID_postaci
        AND o.Umiejętności_Nazwa = m.Nazwa_Umiejętności
WHERE m.wymagania_spelnione
    AND COALESCE(o.poziom, 0) < m.Maksymalny_poziom;


--TECHNIKI
---pełne szczegóły technik
CREATE OR REPLACE VIEW techniki_kategoryzowane AS
SELECT
    t.nazwa,
    t.typ,
    kt.nazwa AS kategoria_funkcjonalna,
    kt.opis AS opis_kategorii,
    t.bazowy_koszt_w_manie,
    t.modyfikatory_kosztu_w_manie,
    t.bazowy_koszt_w_energii,
    t.modyfikatory_kosztu_w_energii,
    t.efekt,
    t.test_sukcesu,
    t.test_trafienia,
    t.testy_obrażeń,
    t.test_na_zniszczenie,
    t.ew_inne_testy
FROM Techniki t 
    INNER JOIN  Techniki_Kategorie tk
        ON t.nazwa = tk.Techniki_nazwa
    INNER JOIN Kategorie_technik kt
        ON tk.Kategorie_technik_nazwa = kt.nazwa;

CREATE OR REPLACE VIEW techniki_sumkategoryzowane AS
SELECT
    nazwa,
    STRING_AGG(kategoria_funkcjonalna, ', ') AS kategorie_funkcjonalne
FROM techniki_kategoryzowane
GROUP BY nazwa;

---lista technik umiejętności

CREATE OR REPLACE VIEW techniki_umiejętności AS
SELECT
    u.Nazwa AS Umiejętność,
    u.Poboczna,
    u.Natura,
    u.Rodzaj,
    u.Samodzielność,
    u.Dostępność,
    t.nazwa AS Technika,
    t.typ,
    t.minimalny_poziom_nauki,
    t.stopień_zaawansowania,
    t.Wymaga_nauki_z_księgii,
    t.Wymaga_nauczyciela,
    t.Wymaga_dodatkowego_treningu,
    t.bazowy_koszt_w_manie,
    t.modyfikatory_kosztu_w_manie,
    t.bazowy_koszt_w_energii,
    t.modyfikatory_kosztu_w_energii,
    t.efekt,
    t.test_sukcesu,
    t.test_trafienia,
    t.testy_obrażeń,
    t.test_na_zniszczenie,
    t.ew_inne_testy
FROM Umiejętności u 
    INNER JOIN Techniki t
        ON u.nazwa=t.Umiejętności_Nazwa ;

---lista technik po postaciach
CREATE OR REPLACE VIEW techniki_postaci AS
SELECT
    P.ID_postaci,
    P.Imię,
    P.Nazwisko,
    t.nazwa AS nazwa_techniki,
    t.typ,
    t.bazowy_koszt_w_manie,
    t.modyfikatory_kosztu_w_manie,
    t.bazowy_koszt_w_energii,
    t.modyfikatory_kosztu_w_energii,
    t.efekt,
    t.test_sukcesu,
    t.test_trafienia,
    t.testy_obrażeń,
    t.test_na_zniszczenie,
    t.ew_inne_testy
FROM Techniki t 
    INNER JOIN zna z
        ON t.nazwa = z.Techniki_nazwa
    INNER JOIN Postacie P
        ON z.Postacie_ID = P.ID_postaci;

---lista technik po przeciwnikach
CREATE OR REPLACE VIEW techniki_przeciwników AS
SELECT
    Pz.Klasy_Przeciwników_nazwa AS Nazwa_Klasy_Przeciwnika,
    t.nazwa AS nazwa_techniki,
    t.typ,
    t.bazowy_koszt_w_manie,
    t.modyfikatory_kosztu_w_manie,
    t.bazowy_koszt_w_energii,
    t.modyfikatory_kosztu_w_energii,
    t.efekt,
    t.test_sukcesu,
    t.test_trafienia,
    t.testy_obrażeń,
    t.test_na_zniszczenie,
    t.ew_inne_testy    
FROM Techniki t 
    INNER JOIN przeciwnicy_znają Pz
        ON t.nazwa = Pz.Techniki_nazwa;


---lista technik po wymaganych przedmiotach
--plan:
--- techniki przedmiotów - lista ogólna technik "posegregowanych" po przedmiotach,
--- wymagane przedmioty - String_agg po technikach listy przedmiotów wymaganych do poszczególnych technik wraz z ich liczebnością(wszelkie możliwe zestawy(po typach, nie egzemplarzach))
CREATE OR REPLACE VIEW techniki_specjalne_przedmiotów AS
SELECT
    Tp.Przed_Nazwa AS nazwa_przedmiotu,
    --inne informacje o przedmiocie?
    Tp.liczba_potrzebnych,
    --informacje o technice? 
    t.nazwa AS nazwa_Techniki,
    t.typ,
    t.bazowy_koszt_w_manie,
    t.modyfikatory_kosztu_w_manie,
    t.bazowy_koszt_w_energii,
    t.modyfikatory_kosztu_w_energii,
    t.efekt,
    t.test_sukcesu,
    t.test_trafienia,
    t.testy_obrażeń,
    t.test_na_zniszczenie,
    t.ew_inne_testy
FROM Techniki t 
    INNER JOIN Techniki_przedmiotów Tp
        ON t.nazwa = Tp.Techniki_nazwa;
--- wymagane przedmioty - String_agg po technikach listy przedmiotów wymaganych do poszczególnych technik wraz z ich liczebnością(wszelkie możliwe zestawy(po typach, nie egzemplarzach))
CREATE OR REPLACE VIEW wymagane_do_technik_przedmioty AS
SELECT
    Techniki_nazwa AS Nazwa_Techniki,
    STRING_AGG(
        liczba_potrzebnych::text || ' ' || Przed_Nazwa,
        ', ' ORDER BY Przed_Nazwa
    ) AS wymagane_przedmioty
FROM Techniki_przedmiotów tp
GROUP BY Nazwa_Techniki;
